#!/usr/bin/env python3
"""Produce human-readable programme tables, not a compression measurement."""
import argparse,csv,json,collections
from pathlib import Path
P=Path(__file__).resolve().parent
BATCHES=[
 ('01_existing_complete_candidates',['L028','F015'],'Independent complete review already assigned to enumeration_review. Reuse phase282/phase278; retain every correction and exact algorithm/table output.','Review and canonical reworking, not rediscovery of the mathematics.'),
 ('02_existing_complete_corrected_components',['L068','L126'],'L068 has accepted literal/repaired graph constructions; L126 has substantial positive source-family proofs and accepted literal-projective obstruction.','Rework L068 accepted17-row proof. For L126 settle a complete corrected source contract and projective replacement; do not count an isolated error as whole recovery.'),
 ('03_projective_and_suzuki',['L056','F003','L043'],'Projective centralizers/inversion, field support and Suzuki normal forms already have proved interfaces in E/D and question packets.','Read full L056/F003 proofs and all L043 Theorem1 branches; preserve Spiga and prior nonchirality attribution. Uniform generation and geometric chirality adapters must be paid.'),
 ('04_forest_and_supported_kernels',['L040','L128'],'B recovers the rank n-1 forest branch; A provides class-two/support normal forms. L128 source has a very concrete all-graph presentation.','Prove L040 rank n-2 three-family exhaustion and geometry; L128 full correlation quotient and lower bounds. No assumption that similar graph words imply all source results.'),
 ('05_existing_geometry_operations',['N005','N006','N007','N014','F005'],'Typed incidence, normal-form, mixing, halving and recognizable-action legs already exist. N006/N007 sources were retrieved before intake closed and must be restored to the target list.','Write exact operation hypotheses/converses and full application contracts; source nonstring flag conditions and every incidence repair remain real obligations.'),
 ('06_older_classification_outputs',['L036','L054','L059','L073','L095'],'D orbit/normalizer enumeration and C quotient recognition are reusable; sources range from2004 to2019 and include substantial census outputs.','Actual atlas input data, complete conjugacy/fusion tables, source labels and quotient admissibility must be reproduced. L073 numerical81/431 agreement does not identify its flawed literal labels.'),
 ('07_broad_matrix_and_permutation_ranks',['L031','F001','L038','L042','L047','F002'],'Existing reflection/IP/rank-reduction and permutation-forest lemmas provide partial legs.','Full uniform generation, all exception ranges and every principal rank/exhaustiveness claim remain unpaid; do not extrapolate from finite checks.'),
 ('08_suzuki_all_parameter_classification',['L110','L114','L115'],'D supplies normalized Suzuki actions; existing partial source proofs give all-rank and omitted-shape evidence.','Recover complete parameter families and output counts, keeping source corrections explicit and sampled Sz8 results distinct from allq statements.'),
 ('09_other_accessible_mathematics',['L007','L003','L033','L041','L045','L046','L050','L063','L064','L070','L071','L091','L096','L120','L121','L122','F004','F006','F007','F008','F009','F011','F012','F017','N010','N011','N012'],'These remain active even where a common incidence umbrella is not yet justified.','Read complete principal proofs and identify exact independent mechanisms; no blanket exclusion by topic, size, editorial form or expected compression.')]
def main():
 a=argparse.ArgumentParser();a.add_argument('--out',type=Path,required=True);a=a.parse_args();j=json.loads((a.out/'inventory.json').read_text());rows=j['entries'];by={r['original_id']:r for r in rows}
 batches=[]
 for k,ids,rationale,obligation in BATCHES:
  batches.append({'batch':k,'original_ids':ids,'rationale':rationale,'next_obligation':obligation,'source_id_statuses':{i:by[i]['proof']['status'] for i in ids},'guaranteed_savings':None,'source_or_question_credit':0})
 covered=set(i for b in batches for i in b['original_ids'])
 remaining=[r['original_id'] for r in rows if r['source_access']['accessible'] and not r['proof']['principal_contract_admitted'] and r['original_id']not in covered]
 batches.append({'batch':'10_remaining_accessible_originals','original_ids':remaining,'rationale':'Every remaining accessible original stays in the programme, including editorial content and partial/question work.','next_obligation':'Read exact full source main statements; recover an honest complete main-result contract or document the absence of new mathematical statements without deleting the original.','guaranteed_savings':None,'source_or_question_credit':0})
 retrieval=[r['original_id'] for r in rows if not r['source_access']['accessible']]
 batches.append({'batch':'11_complete_source_retrieval','original_ids':retrieval,'rationale':'57 original full bodies remain unlocated in this snapshot; old abstracts, previews and component proofs are preserved.','next_obligation':'Locate a legitimate full PDF or full authored rendering. A PDF is not mandatory. Recover exact main results after source access; never treat this batch as excluded.','guaranteed_savings':None,'source_or_question_credit':0})
 (a.out/'prioritized_batches.json').write_text(json.dumps({'scope':'All161 remain active. Priority is an execution order, not an eligibility filter. A source may appear only once in these suggested batches. The27 admitted originals remain separately active for formalization, scope and measurement.','batches':batches},ensure_ascii=False,indent=2)+'\n')
 lines=['All 161 indexed originals','=========================','','This is a per-original recovery inventory, not a new mathematical admission or a compression factor. It preserves all161 original IDs, including inaccessible and uncompressed originals. A source PDF is not required when a complete authored rendering is available.','','Access and recovery','-------------------','','* 104 originals have usable complete representations:100 PDFs and4 non-PDF representations.','* 27 have admitted principal-result contracts;77 accessible originals still need complete recovery.','* 57 remain complete-source retrieval targets. Prior abstracts/previews and partial proofs are retained.','* N006 and N007 explain the old102/current104 access discrepancy.','* No pair of indexed originals is currently confirmed to be merely duplicate editions. Mislabelled duplicate downloads are excluded as access evidence, never as original targets.','','The four non-PDF originals are L022 (complete publisher HTML editorial), L108 and N001 (complete authored browser renderings), and N005 (complete arXiv HTML). N001/L108 original-PDF costs remain missing in historical audits; root is preparing an explicit rendering-coordinate sensitivity. No PDF numerator is invented here.','','Evidence and limits','-------------------','','Every record gives exact source bytes, prior reading scope, source statement candidates, proof packet/admission evidence, proposed theory, measurement status and the next obligation. Numbered statement locations are machine candidates, not a claim to have read every proof. The new bounded source readings are separately identified. All104 accessible originals have an actual target summary; unavailable statements are left pending rather than invented from titles.','','The27 principal contracts retain their exact corrections, ancillary exclusions and classical inputs. They do not assert every printed statement is recovered or every proof is in Lean. Full source-specific formalization remains a separate obligation. No source is dismissed because it does not fit an existing umbrella.','','The two full author candidates F015/L028 are not included in27 admissions. L068 has an independently accepted corrected component covering literal P and repaired Q; L073 has accepted numerical census but unresolved historical table matching. L059 has a structural theory but an unpaid historical census. These distinctions prevent old registry labels from overstating progress.','','Suggested batches','-----------------','']
 for b in batches:
  lines.extend([b['batch'], '~'*len(b['batch']),'',', '.join(b['original_ids'])+'.', '',b['rationale'], '',b['next_obligation'],''])
 lines.extend(['Per-original table','------------------','','For complete machine-readable evidence and exact hashes use inventory.json; inventory.csv is the flat table. The list below preserves the source title and the immediate obligation.',''])
 for r in rows:
  id=r['original_id'];label=id+' — '+r['title'];src=r['source_access']['usable_representations'];access=src[0]['representation']+' ('+src[0]['path']+')' if src else 'complete body pending retrieval'
  lines.extend([label,'~'*len(label),'','Year: '+str(r['year'])+'. Access: '+access+'.','Proof: '+r['proof']['status']+'.','',r['principal_results_to_recover']['summary'] or r['principal_results_to_recover']['bibliographic_target_if_unread'],'','Next: '+r['next_obligation'],''])
 (a.out/'inventory.rst').write_text('\n'.join(lines)+'\n')
 print(json.dumps({'batches':len(batches),'pending_accessible_covered':len(set(i for b in batches[:-1] for i in b['original_ids'])),'retrieval_targets':len(retrieval),'rst_bytes':(a.out/'inventory.rst').stat().st_size}))
if __name__=='__main__':main()
